const storage={set(key,value){try{localStorage.setItem(key,JSON.stringify(value));return true}catch(error){console.error('Failed to save to localStorage:',error);return false}},get(key,defaultValue=null){try{const item=localStorage.getItem(key);return item ? JSON.parse(item): defaultValue}catch(error){console.error('Failed to read from localStorage:',error);return defaultValue}},remove(key){try{localStorage.removeItem(key);return true}catch(error){console.error('Failed to remove from localStorage:',error);return false}},clear(){try{localStorage.clear();return true}catch(error){console.error('Failed to clear localStorage:',error);return false}}};window.Utils={debounce,throttle,isInViewport,smoothScrollTo,getScrollPercentage,formatDate,isValidEmail,sanitizeHTML,copyToClipboard,generateUniqueId,prefersReducedMotion,getDeviceType,loadImage,createElement,storage};